// Page gate for /admin/cyrus/**. Server only.
//   1. role: requireArea(<the tab's area>) (lib/cyrus/admin/perms.ts) - redirects like every admin page;
//   2. private preview: the REAL signed-in account must be on the "modbuilder" allowlist, else a plain
//      404 (the section is indistinguishable from a route that does not exist), like /admin/mod-builder.
// The admin layout already refuses impersonation.
import { notFound } from "next/navigation";
import { getHost, type HostUser } from "../host";
import { CYRUS_ADMIN_TABS, type CyrusAdminTab } from "./perms";

export async function requireCyrusAdmin(tab: CyrusAdminTab): Promise<HostUser> {
  const area = CYRUS_ADMIN_TABS.find((t) => t.id === tab)!.area;
  const host = getHost();
  const user = await host.auth.requireArea(area);
  if (!(await host.access.isPreviewUser(await host.auth.realUser(), "modbuilder"))) notFound();
  return user;
}

export async function cyrusAdminMetadata(title: string) {
  const host = getHost();
  const ok = await host.access.isPreviewUser(await host.auth.realUser().catch(() => null), "modbuilder");
  return { title: ok ? `Cyrus · ${title}` : "Page not found", robots: { index: false, follow: false } };
}

/**
 * Route-handler guard for /api/admin/cyrus/** (r40). Same rule as the pages and the server actions, but returns null
 * instead of redirecting, so the route answers a plain 404: the real account, not impersonating, on the "modbuilder"
 * preview list, with the action's role area. Fails closed on any error.
 */
export async function cyrusAdminApiUser(action: import("./perms").CyrusAdminAction): Promise<HostUser | null> {
  try {
    const { CYRUS_ADMIN_ACTIONS } = await import("./perms");
    const host = getHost();
    const [real, cur] = await Promise.all([host.auth.realUser(), host.auth.currentUser()]);
    if (!real || !cur || real.id !== cur.id) return null;
    if (!host.access.canAccess(real.role, CYRUS_ADMIN_ACTIONS[action])) return null;
    if (!(await host.access.isPreviewUser(real, "modbuilder"))) return null;
    return real;
  } catch {
    return null;
  }
}
// Cyrus admin (/admin/cyrus): who may see each tab and take each action. Pure decisions (server-side:
// it reuses lib/rbac.ts, which imports auth). Unit-tested in test/cyrus-admin.test.ts.
//
// Every tab and every write maps to one admin Area (lib/rbac.ts), so the Cyrus screens follow the
// same role model as the rest of the admin portal:
//   fleet    (ADMIN)            builds, service health, AI cost, cancel / re-run
//   billing  (BILLING + ADMIN)  token balances, grants, refunds, comps
//   support  (SUPPORT + ADMIN)  community moderation (reports, hidden posts, takedowns, suspensions)
//   platform (ADMIN)            game status, networking review + kill switch, Cyrus settings
// On top of the role, the whole section is behind the "modbuilder" private-preview allowlist
// (lib/preview-access.ts), like /admin/mod-builder and /admin/cyrus-tokens, until Cyrus launches.
import type { Role } from "@prisma/client";
import { canAccess, type Area } from "../../rbac";

export const CYRUS_ADMIN_BASE = "/admin/cyrus";

export type CyrusAdminTab = "overview" | "builds" | "users" | "cost" | "reconcile" | "games" | "community" | "library" | "notify" | "flags" | "audit";

export const CYRUS_ADMIN_TABS: { id: CyrusAdminTab; label: string; href: string; area: Area }[] = [
  { id: "overview", label: "Overview", href: CYRUS_ADMIN_BASE, area: "fleet" },
  { id: "builds", label: "Builds", href: `${CYRUS_ADMIN_BASE}/builds`, area: "fleet" },
  { id: "users", label: "Users & tokens", href: `${CYRUS_ADMIN_BASE}/users`, area: "billing" },
  { id: "cost", label: "Cost", href: `${CYRUS_ADMIN_BASE}/cost`, area: "billing" },
  { id: "reconcile", label: "Reconciliation", href: `${CYRUS_ADMIN_BASE}/reconcile`, area: "billing" },
  { id: "games", label: "Games & models", href: `${CYRUS_ADMIN_BASE}/games`, area: "platform" },
  { id: "community", label: "Community", href: `${CYRUS_ADMIN_BASE}/community`, area: "support" },
  { id: "library", label: "Library & safety", href: `${CYRUS_ADMIN_BASE}/library`, area: "fleet" },
  { id: "notify", label: "Notifications", href: `${CYRUS_ADMIN_BASE}/notify`, area: "platform" },
  { id: "flags", label: "Flags & kill switches", href: `${CYRUS_ADMIN_BASE}/flags`, area: "platform" },
  { id: "audit", label: "Audit & settings", href: `${CYRUS_ADMIN_BASE}/audit`, area: "platform" },
];

/** Every write the Cyrus admin can make, with the Area it needs. */
export const CYRUS_ADMIN_ACTIONS = {
  "build.cancel": "fleet",
  "build.rerun": "fleet",
  "build.refund": "billing",
  "build.refund.undo": "billing",
  "tokens.grant": "billing",
  "tokens.revoke": "billing",
  "tokens.comp": "billing",
  "user.suspend": "support",
  "user.unsuspend": "support",
  "report.hide": "support",
  "report.dismiss": "support",
  "post.unhide": "support",
  "page.takedown": "support",
  "page.restore": "support",
  "network.review": "platform",
  "network.killswitch": "platform",
  "game.status": "platform",
  "setting.set": "platform",
  // r40 admin core
  "user.viewas": "support", // read-only staff view (lib/cyrus/admin/viewas.ts), not impersonation
  "user.ban": "support",
  "user.unban": "support",
  "user.ban.nxeon": "platform",
  "user.unban.nxeon": "platform",
  "user.gdpr.export": "platform",
  "user.gdpr.erase": "platform",
  // r40 library moderation (the Library & safety tab is ADMIN: fleet)
  "library.release": "fleet",
  "library.reject": "fleet",
  "library.takedown": "fleet",
  "library.restore": "fleet",
  "library.reports.dismiss": "fleet",
  "library.lists": "fleet",
  "legal.case": "fleet",
  // r40 flags & kill switches
  "flag.launch": "platform",
  "flag.kill": "platform",
  // r40 reconciliation
  "reconcile.wallet": "billing",
  "webhook.replay": "platform",
  // r40 notifications
  "notify.sender": "platform",
} as const satisfies Record<string, Area>;

export type CyrusAdminAction = keyof typeof CYRUS_ADMIN_ACTIONS;

export const isCyrusAdminAction = (v: unknown): v is CyrusAdminAction => typeof v === "string" && v in CYRUS_ADMIN_ACTIONS;

export function canCyrusAdmin(role: Role, action: CyrusAdminAction): boolean {
  return canAccess(role, CYRUS_ADMIN_ACTIONS[action]);
}

export function canSeeCyrusTab(role: Role, tab: CyrusAdminTab): boolean {
  const t = CYRUS_ADMIN_TABS.find((x) => x.id === tab);
  return !!t && canAccess(role, t.area);
}

export function visibleCyrusTabs(role: Role) {
  return CYRUS_ADMIN_TABS.filter((t) => canAccess(role, t.area));
}

/** The first tab a role may open (null = none: the section is not for this role). */
export function landingCyrusTab(role: Role) {
  return visibleCyrusTabs(role)[0] ?? null;
}
// Cyrus admin r40: "view as" = a READ-ONLY staff view of one customer's Cyrus screens (projects, builds, tokens, plan,
// pages, notifications), never Nxeon impersonation (Cyrus refuses impersonated sessions by design, and acting as a
// customer is not needed to support them). Every view starts from an audited action that mints a short grant bound to
// the staff account, the customer and an expiry; the page refuses a missing, foreign or expired grant. PURE + node:crypto.
import { createHmac, timingSafeEqual } from "node:crypto";

export const VIEW_GRANT_MS = 30 * 60_000;

function key(secret: string) {
  return createHmac("sha256", secret).update("cyrus-admin-viewas-v1").digest();
}

export function mintViewGrant(secret: string, adminId: string, userId: string, nowMs: number): string {
  const exp = nowMs + VIEW_GRANT_MS;
  const mac = createHmac("sha256", key(secret)).update(`${adminId}\n${userId}\n${exp}`).digest("base64url");
  return `${exp}.${mac}`;
}

export function checkViewGrant(secret: string, grant: string, adminId: string, userId: string, nowMs: number): boolean {
  const m = /^(\d{13})\.([A-Za-z0-9_-]{43})$/.exec(grant);
  if (!m || !secret) return false;
  const exp = Number(m[1]);
  if (!(exp > nowMs) || exp - nowMs > VIEW_GRANT_MS) return false;
  const want = Buffer.from(createHmac("sha256", key(secret)).update(`${adminId}\n${userId}\n${exp}`).digest("base64url"));
  const got = Buffer.from(m[2]);
  return got.length === want.length && timingSafeEqual(got, want);
}
// Cyrus admin audit trail. Every write made from /admin/cyrus lands here, in the existing AuditLog
// table (no schema change): action `cyrus.admin.<action>`, category "cyrus_admin", target = what it
// was done to, detail = JSON { before, after, note }. The Audit tab lists these rows together with
// the older Cyrus admin actions written by /admin/cyrus-tokens and /admin/cyrus-mods.
import { getHost } from "../host";
import type { CyrusAdminAction } from "./perms";

export const CYRUS_AUDIT_CATEGORY = "cyrus_admin";
export const CYRUS_AUDIT_PREFIX = "cyrus.admin.";

/** Admin actions written by the older Cyrus admin pages (shown in the same list). */
export const LEGACY_CYRUS_ADMIN_ACTIONS = [
  "cyrus.tokens.grant",
  "cyrus.tokens.revoke",
  "cyrus.tokens.tier",
  "cyrus.tokens.settings",
  "cyrusmods.launch",
  "cyrusmods.report.hide",
  "cyrusmods.report.dismiss",
  "cyrusmods.page.hide",
  "cyrusmods.page.unhide",
  "cyrus.lifecycle.setting",
];

export type AuditDetail = { before?: unknown; after?: unknown; note?: string };

const MAX = 4000;

/** JSON for AuditLog.detail, trimmed so one row can never be huge. Pure. */
export function auditDetail(d: AuditDetail): string {
  const s = JSON.stringify({ before: d.before ?? null, after: d.after ?? null, ...(d.note ? { note: d.note.slice(0, 300) } : {}) });
  if (s.length <= MAX) return s;
  return JSON.stringify({ before: "(trimmed)", after: "(trimmed)", note: (d.note ?? "").slice(0, 300), size: s.length });
}

/** Read AuditLog.detail back (our JSON, or a legacy free-text detail). Pure. */
export function readAuditDetail(raw: string | null): AuditDetail & { text?: string } {
  if (!raw) return {};
  if (raw.startsWith("{")) {
    try {
      const v = JSON.parse(raw) as Record<string, unknown>;
      if (v && typeof v === "object" && ("before" in v || "after" in v)) return { before: v.before, after: v.after, note: typeof v.note === "string" ? v.note : undefined };
    } catch { /* legacy text */ }
  }
  return { text: raw };
}

export async function cyrusAudit(i: { actorId: string; action: CyrusAdminAction; target: string; before?: unknown; after?: unknown; note?: string }): Promise<void> {
  await getHost().audit
    .append({ userId: i.actorId, action: CYRUS_AUDIT_PREFIX + i.action, category: CYRUS_AUDIT_CATEGORY, target: i.target.slice(0, 200), detail: auditDetail(i) })
    .catch((e) => console.error("[cyrus-admin] audit write failed", i.action, (e as Error).message));
}

"use server";

/**
* Cyrus admin core (r40) writes: read-only view-as, ban (with optional propagation to the Nxeon account), GDPR erasure.
 * Same contract as lib/actions-cyrus-admin.ts: role area per action (lib/cyrus/admin/perms.ts), the REAL account on the
 * "modbuilder" preview list, never while impersonating, audited before/after (category cyrus_admin), redirect back
 * with ?ok= / ?err=. Lives outside lib/cyrus because it uses Nxeon's own account controls (User.suspended,
 * the Nxeon audit trail); the Cyrus-only logic is in lib/cyrus/admin/ops.ts and gdpr.ts.
 */
import { notFound, redirect } from "next/navigation";
import type { User } from "@prisma/client";
import { db } from "./db";
import { impersonating, realUser } from "./auth";
import { recordAudit } from "./audit";
import { requireArea } from "./rbac";
import { isPreviewUser } from "./preview-access";
import { CYRUS_ADMIN_ACTIONS, CYRUS_ADMIN_BASE, canCyrusAdmin, type CyrusAdminAction } from "./cyrus/admin/perms";
import { cyrusAudit } from "./cyrus/admin/audit";
import { BAN_PREFIX, canViewAs, isBan } from "./cyrus/admin/ops";
import { gdprErase, gdprEraseEnabled, gdprPlanFor } from "./cyrus/admin/gdpr";
import { mintViewGrant } from "./cyrus/admin/viewas";
import { CYRUS_SUSPENSIONS_KEY, loadSuspensions, pruneSuspensions, removeSuspension, upsertSuspension } from "./cyrus/suspensions";

const str = (fd: FormData, k: string, max = 300) => String(fd.get(k) ?? "").trim().slice(0, max);
const ticked = (fd: FormData, k: string) => fd.get(k) === "1" || fd.get(k) === "on";

function go(fd: FormData, kind: "ok" | "err", msg: string): never {
  const b = String(fd.get("back") ?? "");
  const base = b.startsWith(CYRUS_ADMIN_BASE) && !b.includes("//") && b.length < 300 ? b : `${CYRUS_ADMIN_BASE}/users`;
  const [p, q = ""] = base.split("?");
  const params = new URLSearchParams(q);
  params.delete("ok"); params.delete("err");
  params.set(kind, msg.slice(0, 300));
  redirect(`${p}?${params.toString()}`);
}

async function guard(action: CyrusAdminAction): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

async function target(fd: FormData) {
  const v = str(fd, "userId", 64);
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(v)) return null;
  return db.user.findUnique({ where: { id: v }, select: { id: true, email: true, role: true, suspended: true } });
}

/** View the customer's Cyrus screens READ-ONLY (no impersonation): audited, then a 30-minute grant bound to this staff account. */
export async function adminCyrusViewAs(fd: FormData) {
  const admin = await guard("user.viewas");
  const t = await target(fd);
  const ok = canViewAs(admin, t);
  if (!ok.ok) go(fd, "err", ok.error);
  const reason = str(fd, "reason", 200);
  if (reason.length < 3) go(fd, "err", "Give a short reason (support ticket id or why): it is kept in the audit log.");
  const secret = process.env.AUTH_SECRET ?? "";
  if (!secret) go(fd, "err", "View-as is not available on this server (no AUTH_SECRET).");
  await cyrusAudit({ actorId: admin.id, action: "user.viewas", target: `user:${t!.id}`, after: { email: t!.email, readOnly: true, minutes: 30 }, note: reason });
  await recordAudit(admin.id, "cyrus.admin.viewas", `${t!.email}: ${reason}`.slice(0, 300));
  redirect(`${CYRUS_ADMIN_BASE}/view/${encodeURIComponent(t!.id)}?g=${encodeURIComponent(mintViewGrant(secret, admin.id, t!.id, Date.now()))}`);
}

/** Ban from Cyrus: every scope, no end date. With "also suspend the Nxeon account" (ADMIN), the person is signed out everywhere. */
export async function adminCyrusBan(fd: FormData) {
  const admin = await guard("user.ban");
  const t = await target(fd);
  if (!t) go(fd, "err", "No such account.");
  if (t.id === admin.id) go(fd, "err", "You can't ban yourself.");
  if (t.role !== "CUSTOMER") go(fd, "err", "Staff accounts are managed in Nxeon staff settings, not here.");
  const reason = str(fd, "reason", 280);
  if (reason.length < 3) go(fd, "err", "Give a reason (kept in the audit log).");
  if (!ticked(fd, "confirm")) go(fd, "err", "Tick the box to confirm the ban.");
  const propagate = ticked(fd, "nxeon");
  if (propagate && !canCyrusAdmin(admin.role, "user.ban.nxeon")) go(fd, "err", "Only an admin can also suspend the Nxeon account.");
  const now = new Date();
  const list = pruneSuspensions(await loadSuspensions(), now);
  const before = list.find((s) => s.userId === t.id) ?? null;
  const entry = { userId: t.id, scopes: ["build", "community"] as ("build" | "community")[], reason: BAN_PREFIX + reason, by: admin.id, at: now.toISOString(), until: null };
  await db.setting.upsert({ where: { key: CYRUS_SUSPENSIONS_KEY }, update: { value: JSON.stringify(upsertSuspension(list, entry)) }, create: { key: CYRUS_SUSPENSIONS_KEY, value: JSON.stringify(upsertSuspension(list, entry)) } });
  await cyrusAudit({ actorId: admin.id, action: "user.ban", target: `user:${t.id}`, before, after: entry, note: reason });
  if (propagate && !t.suspended) {
    // Nxeon's own lockout: realUser() refuses suspended accounts and the session version bump ends live sessions.
    await db.user.update({ where: { id: t.id }, data: { suspended: true, sessionVersion: { increment: 1 } } });
    await recordAudit(admin.id, "cyrus.admin.nxeon_suspend", `${t.email}: ${reason}`.slice(0, 300));
    await cyrusAudit({ actorId: admin.id, action: "user.ban.nxeon", target: `user:${t.id}`, before: { nxeonSuspended: false }, after: { nxeonSuspended: true }, note: reason });
  }
  go(fd, "ok", `${t.email} banned from Cyrus${propagate ? " and the Nxeon account suspended" : ""}.`);
}

/** Lift a ban. Lifting the Nxeon suspension is a separate tick (ADMIN). */
export async function adminCyrusUnban(fd: FormData) {
  const admin = await guard("user.unban");
  const t = await target(fd);
  if (!t) go(fd, "err", "No such account.");
  const list = await loadSuspensions();
  const before = list.find((s) => s.userId === t.id) ?? null;
  const nx = ticked(fd, "nxeon");
  if (!isBan(before) && !(nx && t.suspended)) go(fd, "err", "That account is not banned.");
  if (nx && !canCyrusAdmin(admin.role, "user.unban.nxeon")) go(fd, "err", "Only an admin can lift a Nxeon account suspension.");
  if (isBan(before)) {
    const next = removeSuspension(list, t.id);
    if (next.length) await db.setting.update({ where: { key: CYRUS_SUSPENSIONS_KEY }, data: { value: JSON.stringify(next) } });
    else await db.setting.deleteMany({ where: { key: CYRUS_SUSPENSIONS_KEY } });
    await cyrusAudit({ actorId: admin.id, action: "user.unban", target: `user:${t.id}`, before, after: null, note: str(fd, "note") });
  }
  if (nx && t.suspended) {
    await db.user.update({ where: { id: t.id }, data: { suspended: false } });
    await recordAudit(admin.id, "cyrus.admin.nxeon_unsuspend", `${t.email}`);
    await cyrusAudit({ actorId: admin.id, action: "user.unban.nxeon", target: `user:${t.id}`, before: { nxeonSuspended: true }, after: { nxeonSuspended: false }, note: str(fd, "note") });
  }
  go(fd, "ok", `Ban lifted for ${t.email}${nx ? " (Nxeon account active again)" : ""}.`);
}

/** GDPR erasure of the person's Cyrus data. Off unless CYRUS_GDPR_ERASE=1; the email must be typed back. */
export async function adminCyrusGdprErase(fd: FormData) {
  const admin = await guard("user.gdpr.erase");
  const t = await target(fd);
  if (!t) go(fd, "err", "No such account.");
  if (!gdprEraseEnabled()) go(fd, "err", "Erasure is switched off on this server (CYRUS_GDPR_ERASE). The plan above is a dry run.");
  if (str(fd, "typed", 200).toLowerCase() !== (t.email ?? "").toLowerCase()) go(fd, "err", "Type the account's email exactly to confirm the erasure.");
  const reason = str(fd, "reason", 200);
  if (reason.length < 3) go(fd, "err", "Give the request reference (kept in the audit log).");
  const plan = await gdprPlanFor(t.id);
  const res = await gdprErase(t.id);
  await cyrusAudit({ actorId: admin.id, action: "user.gdpr.erase", target: `user:${t.id}`, before: { delete: plan.delete, anonymise: plan.anonymise, retain: plan.retain }, after: { deleted: res.deleted, anonymised: res.anonymised, retained: res.retained, anonId: res.anonId }, note: reason });
  go(fd, "ok", `Cyrus data erased for ${t.email}: ${Object.values(res.deleted).reduce((a, b) => a + b, 0)} rows deleted, ${Object.values(res.anonymised).reduce((a, b) => a + b, 0)} anonymised; financial rows kept.`);
}
"use server";

/**
 * Cyrus admin r40: the launch pair and the kill switches. Same contract as lib/actions-cyrus-admin.ts (role area,
 * preview list, never impersonating, audited before/after, redirect back with ?ok= / ?err=).
 *   launch pair  cyrus_studio_public_enabled + cyrus_tok_live are written together, in one transaction, after a typed
 *                confirmation (LAUNCH CYRUS / CLOSE CYRUS). Neither can be changed alone (settings-catalog editAt).
 *   kill switch  killing is one click (the safe direction); resuming needs the confirm box.
 */
import { notFound, redirect } from "next/navigation";
import type { User } from "@prisma/client";
import { db } from "./db";
import { impersonating, realUser } from "./auth";
import { requireArea } from "./rbac";
import { isPreviewUser } from "./preview-access";
import { CYRUS_ADMIN_ACTIONS, CYRUS_ADMIN_BASE, type CyrusAdminAction } from "./cyrus/admin/perms";
import { cyrusAudit } from "./cyrus/admin/audit";
import { KILL_SWITCHES, LAUNCH_PAIR, killWrite, launchPairFlip, launchPairState } from "./cyrus/admin/flags";
import { clearTokenConfigCache } from "./cyrus/tokens/config";

const FLAGS = `${CYRUS_ADMIN_BASE}/flags`;
const str = (fd: FormData, k: string, max = 300) => String(fd.get(k) ?? "").trim().slice(0, max);

function go(kind: "ok" | "err", msg: string, hash = ""): never {
  redirect(`${FLAGS}?${new URLSearchParams({ [kind]: msg.slice(0, 300) }).toString()}${hash}`);
}

async function guard(action: CyrusAdminAction): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

async function stored(keys: readonly string[]) {
  const rows = await db.setting.findMany({ where: { key: { in: [...keys] } } });
  return Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
}

export async function adminCyrusLaunchPair(fd: FormData) {
  const admin = await guard("flag.launch");
  const on = fd.get("on") === "1";
  const before = launchPairState(await stored(LAUNCH_PAIR));
  const f = launchPairFlip(on, str(fd, "typed", 40));
  if (!f.ok) go("err", f.error, "#launch");
  await db.$transaction(f.writes.map((w) => w.value === null ? db.setting.deleteMany({ where: { key: w.key } }) : db.setting.upsert({ where: { key: w.key }, update: { value: w.value }, create: { key: w.key, value: w.value } })));
  clearTokenConfigCache();
  const after = launchPairState(await stored(LAUNCH_PAIR));
  await cyrusAudit({ actorId: admin.id, action: "flag.launch", target: `setting:${LAUNCH_PAIR.join("+")}`, before, after, note: str(fd, "note") });
  go("ok", on ? "Cyrus is public and the token economy is live (both switches on)." : "Cyrus is back to private preview (both switches off).", "#launch");
}

export async function adminCyrusKill(fd: FormData) {
  const admin = await guard("flag.kill");
  const k = KILL_SWITCHES.find((x) => x.id === str(fd, "id", 20));
  if (!k) go("err", "Unknown switch.", "#kill");
  const kill = fd.get("kill") === "1";
  const w = killWrite(k, kill, fd.get("confirm") === "1" || fd.get("confirm") === "on");
  if (!w.ok) go("err", w.error, "#kill");
  const before = (await stored([k.key]))[k.key] ?? null;
  if (w.value === null) await db.setting.deleteMany({ where: { key: w.key } });
  else await db.setting.upsert({ where: { key: w.key }, update: { value: w.value }, create: { key: w.key, value: w.value } });
  await cyrusAudit({ actorId: admin.id, action: "flag.kill", target: `setting:${k.key}`, before: before ?? "(unset)", after: w.value ?? "(unset)", note: `${kill ? "kill" : "resume"}: ${str(fd, "note")}` });
  go("ok", `${k.label}: ${kill ? "stopped" : "running again"}.`, "#kill");
}
"use server";

/**
 * Cyrus admin r40: reconciliation writes (run the wallet top-up reconcile, replay dead webhooks). Same contract as
 * lib/actions-cyrus-admin.ts (role area, preview list, never impersonating, audited, redirect back with ?ok= / ?err=).
 * The wallet reconcile is the existing idempotent sweep (lib/cyrus/tokens/purchase.ts reconcileWalletTopups): it only
 * credits a referenced wallet charge that has no ledger row and no refund, exactly once.
 */
import { notFound, redirect } from "next/navigation";
import type { User } from "@prisma/client";
import { impersonating, realUser } from "./auth";
import { requireArea } from "./rbac";
import { isPreviewUser } from "./preview-access";
import { CYRUS_ADMIN_ACTIONS, CYRUS_ADMIN_BASE, type CyrusAdminAction } from "./cyrus/admin/perms";
import { cyrusAudit } from "./cyrus/admin/audit";
import { reconcileWalletTopups, walletPayEnabled } from "./cyrus/tokens/purchase";
import { sqlOutboxAdmin } from "./cyrus/admin/reconcile";
import { cyrusDb } from "./cyrus/db";

const str = (fd: FormData, k: string, max = 300) => String(fd.get(k) ?? "").trim().slice(0, max);

function go(path: string, kind: "ok" | "err", msg: string): never {
  redirect(`${path}?${new URLSearchParams({ [kind]: msg.slice(0, 300) }).toString()}`);
}

async function guard(action: CyrusAdminAction): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  return admin;
}

const REC = `${CYRUS_ADMIN_BASE}/reconcile`;

export async function adminCyrusReconcileWallet(fd: FormData) {
  const admin = await guard("reconcile.wallet");
  if (!walletPayEnabled()) go(REC, "err", "Wallet top-ups are off (CYRUS_WALLET_PAY): nothing to reconcile.");
  const days = Math.min(30, Math.max(1, Math.floor(Number(fd.get("days"))) || 7));
  const r = await reconcileWalletTopups({ sinceMs: Date.now() - days * 86_400_000 });
  await cyrusAudit({ actorId: admin.id, action: "reconcile.wallet", target: "wallet:cwt", after: { ...r, days }, note: str(fd, "note") });
  go(REC, "ok", `Checked ${r.checked} wallet charge(s) from the last ${days} day(s); credited ${r.credited} that had no tokens.`);
}

export async function adminCyrusReplayWebhook(fd: FormData) {
  const admin = await guard("webhook.replay");
  const ob = sqlOutboxAdmin(cyrusDb);
  if (!(await ob.available().catch(() => false))) go(REC, "err", "The webhook outbox table is not created yet (prisma/manual-migration-cyrus-api-v1.sql).");
  const all = fd.get("all") === "1";
  const id = str(fd, "id", 160);
  if (!all && !/^[A-Za-z0-9_:.-]{1,160}$/.test(id)) go(REC, "err", "Bad event id.");
  const n = all ? await ob.replayAllDead() : await ob.replay(id);
  await cyrusAudit({ actorId: admin.id, action: "webhook.replay", target: all ? "webhook:dead:*" : `webhook:${id}`, after: { requeued: n } });
  go(REC, "ok", n ? `${n} event(s) back to pending (attempts reset). They go out when the outbox dispatcher runs.` : "Nothing to replay (only dead events can be replayed).");
}
