// Cyrus admin core (r40): PURE readers for the upgraded Overview / Builds / Users tabs. No DB, no network (server side: node:crypto).
// Unit-tested in test/cyrus-admin-r40.test.ts. Every figure is computed from rows the caller passes in: nothing here
// invents a number (an empty input gives zeros / null, and the pages show an honest empty state).
import { createHash } from "node:crypto";
import { readStoredFlight } from "../testflight/gate";
import type { Suspension } from "../suspensions";

// ---------------------------------------------------------------------------
// Revenue (spend vs revenue): what customers really PAID for Cyrus tokens, from the token ledger.
// Top-ups carry meta.paidCents (lib/cyrus/tokens/billing.ts + purchase.ts), plan invoices meta.amountPaid. Test-mode
// (livemode false) money is counted apart so a Stripe test run never shows as revenue.
// ---------------------------------------------------------------------------

export type LedgerMoneyRow = { kind: string; source: string | null; meta: unknown };
export type Revenue = { topupCents: number; planCents: number; totalCents: number; purchases: number; testCents: number; unknown: number };

const metaOf = (m: unknown): Record<string, unknown> => (m && typeof m === "object" && !Array.isArray(m) ? (m as Record<string, unknown>) : {});
const cents = (v: unknown) => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.round(v) : null);

export function revenueFromLedger(rows: LedgerMoneyRow[]): Revenue {
  const r: Revenue = { topupCents: 0, planCents: 0, totalCents: 0, purchases: 0, testCents: 0, unknown: 0 };
  for (const row of rows) {
    if (row.kind !== "purchase") continue;
    const m = metaOf(row.meta);
    const paid = row.source === "plan" ? cents(m.amountPaid) : cents(m.paidCents);
    if (paid === null) { r.unknown++; continue; }
    if (m.livemode === false) { r.testCents += paid; continue; }
    r.purchases++;
    if (row.source === "plan") r.planCents += paid; else r.topupCents += paid;
  }
  r.totalCents = r.topupCents + r.planCents;
  return r;
}

// ---------------------------------------------------------------------------
// Test Flight status of recent builds (the boot test stored in ModBuild.cyrus.testFlight)
// ---------------------------------------------------------------------------

export type FlightCounts = { passed: number; failed: number; incomplete: number; notRun: number; pending: number; none: number; total: number };

export function flightSummary(rows: { status: string; cyrus: unknown }[]): FlightCounts {
  const c: FlightCounts = { passed: 0, failed: 0, incomplete: 0, notRun: 0, pending: 0, none: 0, total: 0 };
  for (const r of rows) {
    if (r.status !== "succeeded") continue; // only a built jar can fly
    c.total++;
    const f = readStoredFlight(metaOf(r.cyrus).testFlight);
    if (!f) c.none++;
    else if (f.state === "queued" || f.state === "running") c.pending++;
    else if (f.verdict === "passed") c.passed++;
    else if (f.verdict === "failed") c.failed++;
    else if (f.verdict === "incomplete") c.incomplete++;
    else c.notRun++;
  }
  return c;
}

/** One build's flight in words, for the builds list (null = never queued). */
export function flightLabel(cyrus: unknown): string | null {
  const f = readStoredFlight(metaOf(cyrus).testFlight);
  if (!f) return null;
  if (f.state === "queued" || f.state === "running") return f.state;
  return f.verdict === "not_run" ? "not run" : f.verdict;
}

// ---------------------------------------------------------------------------
// Errors: the most common failure codes in a window
// ---------------------------------------------------------------------------

export type ErrorRow = { code: string; n: number; lastAt: Date; sampleId: string };

export function topErrors(rows: { id: string; status: string; errorCode: string | null; createdAt: Date }[], limit = 8): ErrorRow[] {
  const by = new Map<string, ErrorRow>();
  for (const r of rows) {
    if (r.status !== "failed") continue;
    const code = (r.errorCode || "unknown").slice(0, 60);
    const cur = by.get(code);
    if (!cur) by.set(code, { code, n: 1, lastAt: r.createdAt, sampleId: r.id });
    else { cur.n++; if (r.createdAt > cur.lastAt) { cur.lastAt = r.createdAt; cur.sampleId = r.id; } }
  }
  return [...by.values()].sort((a, b) => b.n - a.n || b.lastAt.getTime() - a.lastAt.getTime()).slice(0, limit);
}

// ---------------------------------------------------------------------------
// Eval status: the owner-ACCEPTED baseline (scripts/cyrus/eval-run.ts writes <out>/<tag>/baseline.json; it is copied
// to services/modbuilder/eval/baseline.json only after the owner accepts the run). Tolerant reader.
// ---------------------------------------------------------------------------

export type EvalStatus = { tag: string | null; at: string | null; prompts: number | null; finalPassPct: number | null; fullPassPct: number | null; spentUsd: number | null };

export function readEvalBaseline(v: unknown): EvalStatus | null {
  const m = metaOf(v);
  const t = metaOf(m.totals);
  const num = (x: unknown) => (typeof x === "number" && Number.isFinite(x) ? x : null);
  if (!Object.keys(m).length || (num(t.finalPassPct) === null && num(t.fullPassPct) === null && num(t.builds) === null)) return null;
  return {
    tag: typeof m.tag === "string" ? m.tag.slice(0, 60) : null,
    at: typeof (m.at ?? m.createdAt) === "string" ? String(m.at ?? m.createdAt).slice(0, 30) : null,
    prompts: num(t.prompts ?? t.builds),
    finalPassPct: num(t.finalPassPct),
    fullPassPct: num(t.fullPassPct),
    spentUsd: num(m.spentUsd),
  };
}

// ---------------------------------------------------------------------------
// Ban = a Cyrus suspension of every scope with no end date. Propagation to the Nxeon account (User.suspended, which
// signs the person out everywhere) is a SEPARATE, ADMIN-only step: lib/actions-cyrus-admin-core.ts.
// ---------------------------------------------------------------------------

export const BAN_PREFIX = "ban: ";
export const isBan = (s: Suspension | null | undefined) => !!s && !s.until && s.scopes.includes("build") && s.scopes.includes("community") && s.reason.startsWith(BAN_PREFIX);

// ---------------------------------------------------------------------------
// GDPR: every Cyrus table that holds a person's data, and what an erasure does to it. Financial rows are RETAINED
// (anonymised later by the owner's retention rule: they back invoices and refunds); content is deleted; shared
// artefacts other people rely on (library contributions, forks) are anonymised, never broken.
// ---------------------------------------------------------------------------

export type GdprPolicy = "delete" | "anonymise" | "retain";
/** `id`: how the person appears in the column: the user id itself (default), or the library's opaque ids
 *  (contributor = HMAC "cyrus-contrib", libraryReporter = "u:" + HMAC viewer id), both keyed by CYRUS_LIBRARY_URL_SECRET. */
export type GdprTable = { model: string; field: string; policy: GdprPolicy; why: string; id?: "contributor" | "libraryReporter" };

export const CYRUS_GDPR_TABLES: GdprTable[] = [
  { model: "modBuild", field: "userId", policy: "anonymise", why: "Build records back token charges; the prompt and plugin name are cleared, the cost row stays." },
  { model: "cyrusProject", field: "userId", policy: "delete", why: "The person's projects (revisions and project assets go with them)." },
  { model: "cyrusModelDraft", field: "ownerRef", policy: "delete", why: "Model Studio autosaves." },
  { model: "cyrusTokenAccount", field: "userId", policy: "retain", why: "Balance record behind paid tokens (financial)." },
  { model: "cyrusTokenLot", field: "userId", policy: "retain", why: "Paid / granted token lots (financial)." },
  { model: "cyrusTokenLedger", field: "userId", policy: "retain", why: "Append-only money ledger (financial, refunds)." },
  { model: "cyrusTokenReservation", field: "userId", policy: "retain", why: "Per-build charges (financial)." },
  { model: "cyrusPlan", field: "userId", policy: "retain", why: "Subscription record (Stripe invoices refer to it)." },
  { model: "cyrusModPage", field: "userId", policy: "delete", why: "Published mod pages." },
  { model: "cyrusModPost", field: "userId", policy: "delete", why: "Community posts." },
  { model: "cyrusModReport", field: "userId", policy: "anonymise", why: "Reports the person filed (the moderation decision must stay explainable)." },
  { model: "cyrusFork", field: "userId", policy: "anonymise", why: "Fork links other creators' pages show." },
  { model: "cyrusModListing", field: "userId", policy: "delete", why: "Marketplace listings." },
  { model: "cyrusModMedia", field: "userId", policy: "delete", why: "Uploaded screenshots / media." },
  { model: "cyrusRemix", field: "userId", policy: "anonymise", why: "Remix credits on other creators' mods." },
  { model: "cyrusModStar", field: "userId", policy: "delete", why: "Stars." },
  { model: "cyrusModRating", field: "userId", policy: "delete", why: "Ratings." },
  { model: "cyrusLibraryItem", field: "userId", policy: "delete", why: "Saved library items." },
  { model: "cyrusCreator", field: "userId", policy: "delete", why: "Creator profile." },
  { model: "cyrusCollection", field: "userId", policy: "delete", why: "Collections." },
  { model: "cyrusCommunityReport", field: "userId", policy: "anonymise", why: "Community reports the person filed." },
  { model: "cyrusCreatorAlert", field: "userId", policy: "delete", why: "Creator alerts (compat watch)." },
  { model: "cyrusCatalogEntry", field: "contributorId", policy: "anonymise", why: "Automatic library contributions other projects use (licence kept, contributor id cleared).", id: "contributor" },
  { model: "cyrusLibraryReport", field: "reporter", policy: "anonymise", why: "Library reports the person filed.", id: "libraryReporter" },
];

export type GdprPlanRow = GdprTable & { rows: number | null };

/** Plan an erasure from per-table row counts (null = the table is not in this database yet). */
export function gdprPlan(counts: Record<string, number | null>): { rows: GdprPlanRow[]; delete: number; anonymise: number; retain: number } {
  const rows = CYRUS_GDPR_TABLES.map((t) => ({ ...t, rows: counts[t.model] ?? null }));
  const sum = (p: GdprPolicy) => rows.filter((r) => r.policy === p).reduce((s, r) => s + (r.rows ?? 0), 0);
  return { rows, delete: sum("delete"), anonymise: sum("anonymise"), retain: sum("retain") };
}

/** The anonymised stand-in for a user id (stable per user, not reversible without the salt kept in the audit row). */
export const ANON_USER = (userId: string, salt: string) => `erased_${createHash("sha256").update(`${salt}:${userId}`).digest("hex").slice(0, 16)}`;

// ---------------------------------------------------------------------------
// View-as: who may be viewed (never staff; never yourself)
// ---------------------------------------------------------------------------

export function canViewAs(admin: { id: string }, target: { id: string; role: string } | null): { ok: true } | { ok: false; error: string } {
  if (!target) return { ok: false, error: "No such account." };
  if (target.id === admin.id) return { ok: false, error: "That is your own account." };
  if (target.role !== "CUSTOMER") return { ok: false, error: "Staff accounts cannot be viewed as (Nxeon rule)." };
  return { ok: true };
}
