function copy(ev: NotifyEvent, d: Record<string, unknown>): { title: string; body: string; path: string | null; cta: string } {
  const name = str(d, "name") || "your mod";
  switch (ev) {
    case "build.finished": {
      const ok = d.status === "succeeded";
      return { title: ok ? `${name} is built` : `${name} did not build`, body: ok ? "Your build finished. Test it, install it on a server, or keep changing it." : `The build stopped${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} The build page shows what happened and what was charged.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: ok ? "Open the build" : "See what happened" };
    }
    case "install.result": {
      const ok = d.ok === true;
      return { title: ok ? `${name} is on ${str(d, "server") || "your server"}` : `${name} was not installed`, body: ok ? (d.restartRequired ? "Installed. Restart the server to load it." : "Installed and loaded.") : `Nothing changed on the server${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} Any partial change was rolled back.`, path: STUDIO, cta: "Open Cyrus" };
    }
    case "mod.outdated":
      return { title: `${name} may need a rebuild`, body: `${str(d, "game") || "The game"} ${str(d, "version") ? `moved to ${str(d, "version")}` : "was updated"}. Your mod was built for ${str(d, "builtFor") || "an older version"}; rebuild it to keep it working.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: "Rebuild" };
    case "takedown":
      return { title: `${name} was taken down`, body: `${str(d, "what") || "Content"} was removed${str(d, "reason") ? ` (${str(d, "reason", 200)})` : ""}. ${d.counterNotice ? "If you believe this is a mistake you can send a counter-notice by replying to this email." : "Projects that used it keep their own copy and keep working."}`, path: STUDIO, cta: "Open Cyrus" };
    case "tokens.low":
      return { title: "Your Cyrus tokens are running low", body: `${str(d, "available") ? `${str(d, "available")} tokens left.` : "Your balance is low."} Top up or change plan to keep building.`, path: STUDIO, cta: "Get tokens" };
  }
}

