// Cyrus support context (r40): tickets stay in Nxeon, but a ticket opened about a Cyrus build carries a snapshot of the
// Cyrus facts support needs (build id, ModSpec revision, Test Flight record, plan / tokens), stored in Cyrus' own table
// CyrusTicketContext keyed by the Nxeon ticket id (no change to Nxeon's Ticket table). The support-side "Cyrus panel"
// reads the snapshot plus live facts. HOST SEAM: Cyrus tables through cyrusDb, the account through host.users.
// SERVER ONLY. Every function fails soft (a missing table or row never breaks ticket creation or the ticket page).
import { cyrusDb as db } from "../db";
import { readCyrusMeta } from "../meta";
import { readStoredFlight } from "../testflight/gate";
import { panelFacts, type CyrusPanel, type ContextSnapshot } from "./panel";

const ID = /^[A-Za-z0-9_-]{1,64}$/;

/** The snapshot for a build the person OWNS (null when it is not theirs or does not exist). */
export async function contextSnapshot(userId: string, buildId: string): Promise<ContextSnapshot | null> {
  if (!ID.test(buildId)) return null;
  const b = await db.modBuild.findUnique({ where: { id: buildId }, select: { id: true, userId: true, status: true, errorCode: true, mcVersion: true, pluginName: true, version: true, cyrus: true, createdAt: true, costUsd: true } }).catch(() => null);
  if (!b || b.userId !== userId) return null;
  const [rev, plan, acct] = await Promise.all([
    db.cyrusRevision.findFirst({ where: { modBuildId: b.id }, orderBy: { seq: "desc" }, select: { id: true, seq: true, projectId: true } }).catch(() => null),
    db.cyrusPlan.findUnique({ where: { userId }, select: { tier: true, status: true, livemode: true } }).catch(() => null),
    db.cyrusTokenAccount.findUnique({ where: { userId }, select: { balance: true, reserved: true, tierOverride: true } }).catch(() => null),
  ]);
  const meta = readCyrusMeta(b.cyrus) as { testFlight?: unknown; model?: string | null };
  const f = readStoredFlight(meta.testFlight);
  return {
    buildId: b.id, status: b.status, errorCode: b.errorCode, mcVersion: b.mcVersion, name: b.pluginName, version: b.version, model: meta.model ?? null, at: b.createdAt.toISOString(),
    projectId: rev?.projectId ?? null, specRevisionId: rev?.id ?? null, specSeq: rev?.seq ?? null,
    flight: f ? { state: f.state, verdict: f.verdict, version: f.version, label: f.label, failed: f.checks.filter((c) => c.status === "fail").map((c) => c.id) } : null,
    plan: plan ? { tier: plan.tier, status: plan.status, live: plan.livemode } : null,
    tokens: acct ? { balance: acct.balance, reserved: acct.reserved, comp: acct.tierOverride } : null,
  };
}

/** Attach the snapshot to a just-created ticket. Best effort: false when the build is not the person's or the table is absent. */
export async function attachTicketContext(ticketId: string, userId: string, buildId: string): Promise<boolean> {
  const snap = await contextSnapshot(userId, buildId);
  if (!snap) return false;
  try {
    await db.cyrusTicketContext.create({ data: { ticketId, userId, buildId: snap.buildId, projectId: snap.projectId, snapshot: snap as never } });
    return true;
  } catch { return false; }
}

/** The support panel for a ticket: the stored snapshot (if any) + live facts about the person's Cyrus account. */
export async function ticketCyrusPanel(ticketId: string, userId: string): Promise<CyrusPanel | null> {
  const [ctx, builds, plan, acct, pages] = await Promise.all([
    db.cyrusTicketContext.findUnique({ where: { ticketId } }).catch(() => null),
    db.modBuild.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 5, select: { id: true, status: true, errorCode: true, pluginName: true, createdAt: true, cyrus: true } }).catch(() => []),
    db.cyrusPlan.findUnique({ where: { userId }, select: { tier: true, status: true, livemode: true } }).catch(() => null),
    db.cyrusTokenAccount.findUnique({ where: { userId }, select: { balance: true, reserved: true, tierOverride: true, tierOverrideUntil: true } }).catch(() => null),
    db.cyrusModPage.count({ where: { userId } }).catch(() => 0),
  ]);
  return panelFacts({ snapshot: (ctx?.snapshot as ContextSnapshot | undefined) ?? null, builds, plan, acct, pages });
}
