export async function POST(req: Request) {
  const cfg = await loadGatewayConfig();
  if (cfg.killSwitch) return json(503, { error: "gateway_killed", message: "Nxeon AI is paused for all mods right now." });
  if (!cfg.enabled) return json(503, { error: "gateway_off", message: "Nxeon AI for mods is not available yet." });

  const auth = req.headers.get("authorization") || "";
  const claims = verifyGatewayToken(auth.startsWith("Bearer ") ? auth.slice(7) : "", { maxAgeMs: await gatewayTokenMaxAgeMs() });
