  const rl = checkRateLimit(`cyrus-ai-gw:${claims.serverId}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) return json(429, { error: "rate_limited" }, { "Retry-After": String(rl.retryAfterSec) });

  const raw = await req.text();
  if (raw.length > 16_000) return json(413, { error: "too_large" });
  let body: { prompt?: unknown; maxOutputTokens?: unknown };
  try { body = JSON.parse(raw || "{}"); } catch { return json(400, { error: "bad_json" }); }
  const prompt = typeof body.prompt === "string" ? body.prompt : "";
  if (!prompt.trim()) return json(400, { error: "prompt_required" });

  // Stub: no owner-budget or usage store yet, so the owner's settings are the defaults
  // (AI off, budget 0) and the call is refused with the reason the mod would really see.
  const now = new Date();
  const d = decideCall({
    cfg, budget: DEFAULT_OWNER_BUDGET, usage: EMPTY_USAGE, promptChars: prompt.length,
    requestedMaxOutput: typeof body.maxOutputTokens === "number" ? body.maxOutputTokens : undefined,
    secondsToNextMinute: 60 - now.getUTCSeconds(), secondsToReset: secondsToUtcMidnight(now),
