export function verifyGatewayToken(token: string | null | undefined, opts: { nowMs?: number; maxAgeMs?: number } = {}): GatewayTokenClaims | null {
  const nowMs = opts.nowMs ?? Date.now();
  const maxAgeMs = opts.maxAgeMs ?? GATEWAY_TOKEN_DEFAULT_MAX_AGE_DAYS * 86_400_000;
  const parts = String(token || "").split(".");
  if (parts.length !== 3 || parts[0] !== TOKEN_PREFIX) return null;
  const want = createHmac("sha256", key()).update(`${parts[0]}.${parts[1]}`).digest();
  const got = Buffer.from(parts[2], "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) return null;
  try {
    const p = JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8")) as { s?: unknown; m?: unknown; iat?: unknown };
    if (typeof p.s !== "string" || typeof p.m !== "string" || typeof p.iat !== "number" || !Number.isFinite(p.iat)) return null;
    // expired, or issued in the future (clock abuse): refused
    if (p.iat > nowMs + FUTURE_SKEW_MS || nowMs - p.iat > maxAgeMs) return null;
    return { serverId: p.s, modId: p.m, issuedAt: p.iat };
