}

/** First touch wins for 30 days, except a NEW referral code (an explicit partner link) replaces the old one. */
export function mergeAttribution(prev: Attribution | null, next: Attribution | null, nowMs: number): Attribution | null {
  if (!next) return prev;
  if (!prev || !prev.at || nowMs - prev.at > ATTR_MAX_AGE_S * 1000) return next;
