    <div role="dialog" aria-modal="false" aria-labelledby="cyrus-consent-title" className="fixed inset-x-3 bottom-3 z-[60] mx-auto max-w-xl rounded-2xl border border-white/10 bg-[#07070c]/95 p-4 text-white shadow-2xl backdrop-blur sm:inset-x-6 sm:bottom-6">
