// Reads
// ---------------------------------------------------------------------------

export type TokenSummary = {
  balance: number;
  reserved: number;
  available: number;
  /** r41: tokens held but not spendable (a lapsed plan's tokens under the freeze rule). Included in balance. */
  frozen: number;
  bySource: Record<string, number>;
  nextExpiry: { at: string; amount: number } | null;
  lifetimeGranted: number;
  lifetimeSpent: number;
};

/** Live summary (ignores lots that are past expiry but not swept yet). */
export async function tokenSummary(userId: string, now = new Date()): Promise<TokenSummary> {
  const live = { userId, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] };
  const [lots, held, acct, plan] = await Promise.all([
    db.cyrusTokenLot.findMany({ where: live, select: { source: true, remaining: true, expiresAt: true }, orderBy: { expiresAt: { sort: "asc", nulls: "last" } } }),
    db.cyrusTokenReservation.aggregate({ where: { userId, status: "held" }, _sum: { amount: true } }),
    db.cyrusTokenAccount.findUnique({ where: { userId } }),
    db.cyrusPlan.findUnique({ where: { userId }, select: { status: true, endedAt: true, currentPeriodEnd: true } }),
  ]);
  const frozenSrc = plan && planTokensFrozen(plan, await loadTokenConfig(), now) ? ["plan"] : [];
  const bySource: Record<string, number> = {};
  let balance = 0;
  for (const l of lots) { balance += l.remaining; bySource[l.source] = (bySource[l.source] ?? 0) + l.remaining; }
  const first = lots.find((l) => l.expiresAt);
  const reserved = held._sum.amount ?? 0;
  const frozen = lots.filter((l) => frozenSrc.includes(l.source)).reduce((a, l) => a + l.remaining, 0);
  return {
    balance, reserved, available: Math.max(0, balance - frozen - reserved), frozen, bySource,
    nextExpiry: first?.expiresAt ? { at: first.expiresAt.toISOString(), amount: lots.filter((l) => l.expiresAt && l.expiresAt.getTime() === first.expiresAt!.getTime()).reduce((a, l) => a + l.remaining, 0) } : null,
    lifetimeGranted: acct?.lifetimeGranted ?? 0,
    lifetimeSpent: acct?.lifetimeSpent ?? 0,
  };
}

export async function ledgerPage(userId: string, opts: { take?: number; before?: string | null } = {}) {
  const take = Math.min(100, Math.max(1, opts.take ?? 30));
  const rows = await db.cyrusTokenLedger.findMany({
    where: { userId, ...(opts.before ? { createdAt: { lt: new Date(opts.before) } } : {}) },
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    take: take + 1,
  });
  return { rows: rows.slice(0, take), more: rows.length > take };
}

// Cyrus tokens that come with a game server: once on purchase, again on every paid
// renewal (less than the first grant). Server only; plain module (called from the worker's
// renewal sweep and from placeGameOrder / renewNow). Every entry point is BEST-EFFORT:
// callers wrap it so a token hiccup can never fail an order or a renewal.
//
// Idempotent per server + period: `gs:<serverId>:initial`, `gs:<serverId>:renew:<periodStartISO>`.
// A webhook retry, a re-run sweep or a double "Renew now" never grants twice.
import { cyrusDb as db } from "../db";
import { loadTokenConfig } from "./config";
import { serverGrant } from "./economy";
import { creditTokens, revokeTokens, type CreditResult, type Tx } from "./ledger";
import { tokensActiveForUserId } from "./access";
import { earnsCyrusTokens } from "./games";
import { getHost } from "../host";

const DAY = 86_400_000;
export const initialKey = (serverId: string) => `gs:${serverId}:initial`;
export const renewalKey = (serverId: string, periodStart: Date) => `gs:${serverId}:renew:${periodStart.toISOString()}`;

type GrantCtx = { userId: string; serverId: string; gameFamily?: string | null };

async function eligible(c: GrantCtx): Promise<boolean> {
  const cfg = await loadTokenConfig();
  // r41 scope (PLACEHOLDER setting cyrus_tok_grant_scope): cyrus_games = servers of a game Cyrus builds for (registry
  // status "live", the pre-r41 rule); all_game_servers = any game server; all_servers = any paid Nxeon server.
  if (cfg.grant.scope !== "all_servers") {
    const fam = c.gameFamily ?? await getHost().servers.planFamily(c.serverId);
    if (cfg.grant.scope === "cyrus_games" ? !earnsCyrusTokens(fam) : !fam) return false;
  }
  return tokensActiveForUserId(c.userId, cfg);
}

/** Tokens this server has ever been granted (gross: a reversal does not make room again), for the per-server lifetime cap. */
async function serverLifetime(tx: Tx, serverId: string) {
  const a = await tx.cyrusTokenLedger.aggregate({ where: { sourceRef: serverId, source: { in: ["server_initial", "server_renewal"] }, kind: "grant" }, _sum: { delta: true } });
  return a._sum.delta ?? 0;
}

/** Apply the per-server lifetime cap and the per-account held cap (in that order). */
async function capServerGrant(tx: Tx, userId: string, serverId: string, amount: number, at: Date, cfg: Awaited<ReturnType<typeof loadTokenConfig>>) {
  let note: string | undefined;
  if (cfg.grant.perServerCap > 0) {
    const room = Math.max(0, cfg.grant.perServerCap - (await serverLifetime(tx, serverId)));
    if (amount > room) { amount = room; note = `capped at ${cfg.grant.perServerCap} tokens per server`; }
  }
  const held = await serverGrantBalance(tx, userId, at);
  const room = Math.max(0, cfg.grant.balanceCap - held);
  if (amount > room) { amount = room; note = `capped at ${cfg.grant.balanceCap} server tokens held`; }
  return { amount, note };
}

/** Server-grant tokens the account still holds, for the per-account cap. */
async function serverGrantBalance(tx: Tx, userId: string, now: Date) {
  const a = await tx.cyrusTokenLot.aggregate({
    where: { userId, source: { in: ["server_initial", "server_renewal"] }, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] },
    _sum: { remaining: true },
  });
  return a._sum.remaining ?? 0;
}

/**
 * Purchase grant. `chargeCents` is what the order actually charged for `termMonths`
 * (after coupons/partner discounts, pre-tax); a $0 order (trial) earns nothing now and
 * gets its initial grant on its first paid renewal instead.
 */
export async function grantForGameServerPurchase(c: GrantCtx & { chargeCents: number; termMonths: number; now?: Date }): Promise<CreditResult | null> {
  if (!(c.chargeCents > 0)) return null;
  if (!(await eligible(c))) return null;
  const cfg = await loadTokenConfig();
  const term = Math.max(1, Math.round(c.termMonths || 1));
  const monthlyCents = Math.round(c.chargeCents / term);
  const g = serverGrant("initial", monthlyCents, term, cfg);
  if (!g.tokens) return null;
  const now = c.now ?? new Date();
  return creditTokens({
    userId: c.userId,
    amount: g.tokens,
    kind: "grant",
    source: "server_initial",
    sourceRef: c.serverId,
    idemKey: initialKey(c.serverId),
    expiresAt: new Date(now.getTime() + g.expiresInDays * DAY),
    note: "Game server purchase",
    meta: { monthlyCents, termMonths: term, formula: { initialPerMonth: g.initialPerMonth, renewPerMonth: g.renewPerMonth, months: g.months } },
    now,
    clamp: async (tx, amount, at) => {
      // Abuse limits: a handful of initial grants per 30 days, and a ceiling on held server tokens.
      const recent = await tx.cyrusTokenLedger.count({ where: { userId: c.userId, source: "server_initial", kind: "grant", delta: { gt: 0 }, createdAt: { gt: new Date(at.getTime() - 30 * DAY) } } });
      if (recent >= cfg.grant.maxInitialPer30d) return { amount: 0, note: `capped: ${recent} server grants in 30 days` };
      return capServerGrant(tx, c.userId, c.serverId, amount, at, cfg);
    },
  });
}

/**
 * Paid-renewal grant. `netCents` = the renewal's pre-tax charge for `months`. If this server
 * never got its initial grant (bought with a $0 trial, or before tokens existed for this
 * account) the first paid renewal earns the initial amount instead.
 */
export async function grantForGameServerRenewal(c: GrantCtx & { netCents: number; months: number; periodStart: Date; now?: Date }): Promise<CreditResult | null> {
  if (!(c.netCents > 0)) return null;
  if (!(await eligible(c))) return null;
  const had = await db.cyrusTokenLedger.findUnique({ where: { idemKey: initialKey(c.serverId) }, select: { id: true } });
  if (!had) return grantForGameServerPurchase({ userId: c.userId, serverId: c.serverId, gameFamily: c.gameFamily, chargeCents: c.netCents, termMonths: c.months, now: c.now });
  const cfg = await loadTokenConfig();
  const months = Math.max(1, Math.round(c.months || 1));
  const monthlyCents = Math.round(c.netCents / months);
  const g = serverGrant("renewal", monthlyCents, months, cfg);
  if (!g.tokens) return null;
  const now = c.now ?? new Date();
  return creditTokens({
    userId: c.userId,
    amount: g.tokens,
    kind: "grant",
    source: "server_renewal",
    sourceRef: c.serverId,
    idemKey: renewalKey(c.serverId, c.periodStart),
    expiresAt: new Date(now.getTime() + g.expiresInDays * DAY),
    note: "Game server renewal",
    meta: { monthlyCents, months, periodStart: c.periodStart.toISOString() },
    now,
    clamp: (tx, amount, at) => capServerGrant(tx, c.userId, c.serverId, amount, at, cfg),
  });
}

export type ReverseReason = "refund" | "cancel" | "deleted";

/**
 * r41: take back a server's UNSPENT grant tokens (never below zero, never tokens a running build holds). `refund` and
 * `cancel` always reverse; `deleted` only within cyrus_tok_grant_clawback_days of the server's first grant (deploy and
 * delete farming). Idempotent per server + reason + ref (`gs:<serverId>:reverse:<reason>:<ref>`).
 */
export async function reverseServerGrants(c: { userId: string; serverId: string; reason: ReverseReason; ref?: string | null; now?: Date }): Promise<{ revoked: number; skipped?: string }> {
  const now = c.now ?? new Date();
  const cfg = await loadTokenConfig();
  const first = await db.cyrusTokenLedger.findUnique({ where: { idemKey: initialKey(c.serverId) }, select: { userId: true, createdAt: true } });
  if (!first || first.userId !== c.userId) return { revoked: 0, skipped: "no grant" };
  if (c.reason === "deleted" && !(cfg.grant.clawbackDays > 0 && now.getTime() - first.createdAt.getTime() <= cfg.grant.clawbackDays * DAY)) return { revoked: 0, skipped: "outside clawback window" };
  const lots = await db.cyrusTokenLot.findMany({ where: { userId: c.userId, sourceRef: c.serverId, source: { in: ["server_initial", "server_renewal"] }, remaining: { gt: 0 } }, select: { id: true, remaining: true } });
  const want = lots.reduce((a, l) => a + l.remaining, 0);
  const ref = (c.ref ?? "once").replace(/[^A-Za-z0-9_:.-]/g, "").slice(0, 80) || "once";
  const r = await revokeTokens({
    userId: c.userId, amount: want, lotIds: lots.map((l) => l.id), sourceRef: c.serverId, now,
    idemKey: `gs:${c.serverId}:reverse:${c.reason}:${ref}`,
    note: c.reason === "refund" ? "Server refunded" : c.reason === "cancel" ? "Server cancelled" : "Server deleted soon after deploy",
    meta: { serverId: c.serverId, reason: c.reason },
  });
  return { revoked: r.revoked };
}

/** Wrappers for the order/renewal code paths: never throw, log instead. */
export async function safeGrantPurchase(c: Parameters<typeof grantForGameServerPurchase>[0]): Promise<void> {
  try { await grantForGameServerPurchase(c); } catch (e) { console.error("[cyrus-tokens] purchase grant failed", c.serverId, (e as Error).message); }
}
export async function safeReverseServerGrants(c: Parameters<typeof reverseServerGrants>[0]): Promise<void> {
  try { await reverseServerGrants(c); } catch (e) { console.error("[cyrus-tokens] server grant reversal failed", c.serverId, (e as Error).message); }
}
export async function safeGrantRenewal(c: Parameters<typeof grantForGameServerRenewal>[0]): Promise<void> {
  try { await grantForGameServerRenewal(c); } catch (e) { console.error("[cyrus-tokens] renewal grant failed", c.serverId, (e as Error).message); }
}
// r41 plan-token rollover + lapse rules. Pure (unit-tested); the ledger and billing call these.
//
//  - rolloverMode "while_active" (default): a month's plan tokens carry into the next month for as long as the plan
//    stays active (no age limit). "age": the pre-r41 rule (each month's tokens last rolloverMonths).
//  - rolloverCapMonths > 0: plan tokens held never exceed N months of the plan's tokens; the excess of a new month is
//    not credited (nothing already held is taken, so a replayed invoice can never expire paid tokens).
//  - lapseRule, when the plan ends: freeze_then_expire = kept, not spendable, back on resubscribe within the grace,
//    gone after it; grace_then_expire = spendable during the grace, then gone; expire = gone at the period end.
//    Top-ups, server grants, the starter and admin grants are separate lots and never follow the plan.
import type { TokenConfig } from "./config";

const DAY = 86_400_000;

export type PlanRow = { status: string; endedAt: Date | null; currentPeriodEnd: Date | null } | null;

/** The plan counts as active for rollover: active/trialing, or past_due inside the retry grace. */
export function planActive(plan: PlanRow, cfg: TokenConfig, now: Date): boolean {
  if (!plan || plan.endedAt) return false;
  if (plan.status === "active" || plan.status === "trialing") return true;
  if (plan.status === "past_due") return !plan.currentPeriodEnd || now.getTime() <= plan.currentPeriodEnd.getTime() + cfg.plan.pastDueGraceDays * DAY;
  return false;
}

/** Plan lots are frozen (held, not spendable) while a lapsed plan sits in its freeze grace. */
export function planTokensFrozen(plan: PlanRow, cfg: TokenConfig, now: Date): boolean {
  return cfg.plan.lapseRule === "freeze_then_expire" && !!plan && !planActive(plan, cfg, now);
}

/** Expiry of a newly granted month of plan tokens: none while active (while_active), else the age rule. */
export function planGrantExpiry(grantedAt: Date, cfg: TokenConfig): Date | null {
  return cfg.plan.rolloverMode === "while_active" ? null : new Date(grantedAt.getTime() + Math.round(cfg.plan.rolloverMonths * 31) * DAY);
}

/** When a lapsed plan's tokens expire. */
export function lapseExpiry(periodEnd: Date, cfg: TokenConfig): Date {
  return cfg.plan.lapseRule === "expire" ? periodEnd : new Date(periodEnd.getTime() + cfg.plan.cancelGraceDays * DAY);
}

/** How much of a new month may be credited under the rollover cap (Infinity = no cap). */
export function rolloverRoom(heldPlanTokens: number, monthlyTokens: number, cfg: TokenConfig): number {
  if (!(cfg.plan.rolloverCapMonths > 0)) return Number.POSITIVE_INFINITY;
  return Math.max(0, Math.floor(cfg.plan.rolloverCapMonths * monthlyTokens) - heldPlanTokens);
}

/** The rules in customer words, for the plans/tokens screens and build cost screens. */
export function rolloverRulesCopy(cfg: TokenConfig): string[] {
  const lines: string[] = [];
  if (cfg.plan.rolloverMode === "while_active") {
    lines.push("Unused plan tokens roll over to the next month for as long as your plan stays active.");
    if (cfg.plan.rolloverCapMonths > 0) lines.push(`Rollover is capped at ${cfg.plan.rolloverCapMonths} month${cfg.plan.rolloverCapMonths === 1 ? "" : "s"} of your plan's tokens.`);
  } else {
    lines.push(`Unused plan tokens roll over for up to ${cfg.plan.rolloverMonths} month${cfg.plan.rolloverMonths === 1 ? "" : "s"}.`);
  }
  const g = cfg.plan.cancelGraceDays;
  if (cfg.plan.lapseRule === "freeze_then_expire") lines.push(g > 0 ? `If your plan ends, its tokens are paused for ${g} days: resubscribe in that time and you get them back, after that they expire.` : "If your plan ends, its tokens expire.");
  else if (cfg.plan.lapseRule === "grace_then_expire") lines.push(g > 0 ? `If your plan ends, you can still use its tokens for ${g} days, then they expire.` : "If your plan ends, its tokens expire.");
  else lines.push("If your plan ends, its tokens expire at the end of the period you paid for.");
  lines.push("Tokens you buy as a top-up and tokens from your Nxeon servers are separate: they never depend on your plan.");
  return lines;
}

/** Server-grant rules in customer words. */
export function serverGrantRulesCopy(cfg: TokenConfig): string[] {
  const which = cfg.grant.scope === "all_servers" ? "every paid server" : cfg.grant.scope === "all_game_servers" ? "every paid game server" : "every paid game server Cyrus builds for";
  const lines = [`You get free tokens with ${which} you deploy on Nxeon, and more on each paid renewal.`, `Server tokens last at least ${cfg.grant.expiryDays} days.`];
  if (cfg.grant.clawbackDays > 0) lines.push(`Refunding a server, or deleting it within ${cfg.grant.clawbackDays} days, takes back that server's unspent tokens.`);
  else lines.push("Refunding a server takes back that server's unspent tokens.");
  return lines;
}
// Cyrus token spend, read side: the live meter of a running build and the spend breakdown of a mod (every version,
// change and asset build of one project). Server only; reads the reservation + ledger the economy already writes.
//
// Honest numbers:
//  - "estimated": tokensForCost(the AI usage the builder has reported so far). It moves while the build runs and is
//    NOT a charge; the account only ever pays what settle decides.
//  - "settled": the ledger's settle row (charged, returned to the balance, and what Nxeon wrote off).
import type { Prisma } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { isCyrusModel, type CyrusModelId } from "../models";
import { readCyrusMeta } from "../meta";
import { loadTokenConfig, type TokenConfig } from "./config";
import { tokensForCost } from "./economy";

export type SpendState = "running" | "settling" | "settled" | "released" | "untracked";

export type BuildSpend = {
  buildId: string;
  model: CyrusModelId;
  state: SpendState;
  /** Tokens held when it started (0 = untracked or not reserved). */
  held: number;
  /** From the AI usage reported so far; an estimate, never a charge. */
  estimated: number;
  /** Final figures once settled (null while running). */
  charged: number | null;
  returned: number | null;
  writeoff: number;
  reason: string | null;
  settledAt: string | null;
};

type Res = { amount: number; status: string; charged: number | null; model: string; settledAt: Date | null } | null;
type Build = { id: string; status: string; costUsd: number; cyrus: Prisma.JsonValue | null };
type Settle = { delta: number; note: string | null; meta: Prisma.JsonValue | null; createdAt: Date } | null;

const TERMINAL = new Set(["succeeded", "failed"]);

/** Pure: one build's spend from its rows. */
export function buildSpendFrom(b: Build, res: Res, settle: Settle, cfg: TokenConfig): BuildSpend {
  const model: CyrusModelId = res && isCyrusModel(res.model) ? res.model : (readCyrusMeta(b.cyrus).model ?? "saka");
  const estimated = tokensForCost(b.costUsd || 0, model, cfg);
  if (!res) return { buildId: b.id, model, state: "untracked", held: 0, estimated, charged: null, returned: null, writeoff: 0, reason: null, settledAt: null };
  if (res.status === "held") return { buildId: b.id, model, state: TERMINAL.has(b.status) ? "settling" : "running", held: res.amount, estimated, charged: null, returned: null, writeoff: 0, reason: null, settledAt: null };
  const m = (settle?.meta ?? {}) as { released?: number; writeoff?: number };
  const charged = res.charged ?? Math.max(0, -(settle?.delta ?? 0));
  return {
    buildId: b.id, model, state: res.status === "settled" ? "settled" : "released", held: res.amount, estimated,
    charged, returned: typeof m.released === "number" ? m.released : Math.max(0, res.amount - charged), writeoff: typeof m.writeoff === "number" ? m.writeoff : 0,
    reason: settle?.note ?? null, settledAt: (res.settledAt ?? settle?.createdAt)?.toISOString() ?? null,
  };
}

async function load(userId: string, builds: Build[]): Promise<BuildSpend[]> {
  if (!builds.length) return [];
  const ids = builds.map((b) => b.id);
  const [cfg, res, settles] = await Promise.all([
    loadTokenConfig(),
    db.cyrusTokenReservation.findMany({ where: { buildId: { in: ids }, userId }, select: { buildId: true, amount: true, status: true, charged: true, model: true, settledAt: true } }),
    db.cyrusTokenLedger.findMany({ where: { userId, idemKey: { in: ids.map((i) => `settle:${i}`) } }, select: { buildId: true, delta: true, note: true, meta: true, createdAt: true } }),
  ]);
  const r = new Map(res.map((x) => [x.buildId, x]));
  const s = new Map(settles.map((x) => [x.buildId, x]));
  return builds.map((b) => buildSpendFrom(b, r.get(b.id) ?? null, s.get(b.id) ?? null, cfg));
}

/** The live meter for one of the user's builds (null = not theirs). */
export async function liveBuildSpend(userId: string, buildId: string): Promise<BuildSpend | null> {
  const b = await db.modBuild.findUnique({ where: { id: buildId }, select: { id: true, userId: true, status: true, costUsd: true, cyrus: true } });
  if (!b || b.userId !== userId) return null;
  return (await load(userId, [b]))[0];
}

export type SpendRow = BuildSpend & { seq: number; kind: "first build" | "change" | "asset" | "import" | "revert"; label: string; status: string; createdAt: string };
export type ModSpend = {
  rootId: string;
  rows: SpendRow[];
  total: { charged: number; returned: number; writeoff: number; running: number; estimatedRunning: number; builds: number };
};

// CyrusRevision kinds (engine-core/revisions.ts): asset + config edits are asset operations.
const ASSET_KINDS = new Set(["asset", "config"]);

/** Pure: totals + per-row kind/label for a mod's builds (oldest first). */
export function modSpendFrom(rootId: string, builds: (Build & { createdAt: Date; changeRequest: string | null; prompt: string; baseBuildId: string | null })[], spend: BuildSpend[], revKind: Map<string, string>): ModSpend {
  const rows: SpendRow[] = builds.map((b, i) => {
    const rk = revKind.get(b.id) ?? "";
    const kind: SpendRow["kind"] = rk === "revert" ? "revert" : rk === "imported" ? "import" : ASSET_KINDS.has(rk) ? "asset" : b.baseBuildId ? "change" : "first build";
    const text = (b.changeRequest || b.prompt || "").replace(/\s+/g, " ").trim();
    return { ...spend[i], seq: i + 1, kind, label: text.length > 90 ? `${text.slice(0, 87)}...` : text, status: b.status, createdAt: b.createdAt.toISOString() };
  });
  const total = { charged: 0, returned: 0, writeoff: 0, running: 0, estimatedRunning: 0, builds: rows.length };
  for (const r of rows) {
    total.charged += r.charged ?? 0;
    total.returned += r.returned ?? 0;
    total.writeoff += r.writeoff;
    if (r.state === "running" || r.state === "settling") { total.running++; total.estimatedRunning += r.estimated; }
  }
  return { rootId, rows, total };
}

/** Spend breakdown of one of the user's mods: `anyBuildId` may be the root or any version of it. */
export async function modSpend(userId: string, anyBuildId: string): Promise<ModSpend | null> {
  const b = await db.modBuild.findUnique({ where: { id: anyBuildId }, select: { userId: true, id: true, rootBuildId: true } });
  if (!b || b.userId !== userId) return null;
  const rootId = b.rootBuildId ?? b.id;
  const builds = await db.modBuild.findMany({
    where: { userId, OR: [{ id: rootId }, { rootBuildId: rootId }] },
    orderBy: { createdAt: "asc" },
    take: 500,
    select: { id: true, status: true, costUsd: true, cyrus: true, createdAt: true, changeRequest: true, prompt: true, baseBuildId: true },
  });
  const revs = await db.cyrusRevision.findMany({ where: { modBuildId: { in: builds.map((x) => x.id) } }, select: { modBuildId: true, kind: true } });
