// CYRUS SIDE: the receiver of Nxeon -> Cyrus platform events (lib/nxeon-platform/events.ts on the sending side).
//   headers  Nxeon-Webhook-Id, Nxeon-Webhook-Timestamp, Nxeon-Signature: v1=<hex HMAC-SHA256(secret, id.ts.body)>
//   rule     signature + 300 s window first; an id is remembered as DONE only after its handler succeeded, so a failed
//            handler (500) is redelivered and applied, never swallowed as a duplicate. Handlers are idempotent anyway.
// Handlers are passed in (the route wires the real ones), so this file is pure apart from crypto. HOST SEAM: no platform imports.
import { createHmac } from "node:crypto";
import { safeEqual } from "../api/v1/signing";

export const PLATFORM_EVENT_TOLERANCE_S = 300;
export const PLATFORM_EVENT_MAX_BODY = 256 * 1024;
export type PlatformEventIn = { id: string; type: string; createdAt: string; subject: string | null; data: Record<string, unknown> };
export type PlatformEventHandlers = Partial<Record<string, (e: PlatformEventIn) => Promise<unknown>>>;

export function createDoneSet(ttlMs = 24 * 3600_000, max = 50_000) {
  const m = new Map<string, number>();
  return {
    has(id: string, now = Date.now()) { const t = m.get(id); return t !== undefined && t > now; },
    add(id: string, now = Date.now()) { if (m.size >= max) for (const k of m.keys()) { m.delete(k); if (m.size < max * 0.9) break; } m.set(id, now + ttlMs); },
  };
}
export type DoneSet = ReturnType<typeof createDoneSet>;

export async function receivePlatformEvent(req: Request, o: { secret: string; handlers: PlatformEventHandlers; done: DoneSet; nowMs?: number }): Promise<Response> {
  const now = o.nowMs ?? Date.now();
  const body = await req.text();
  if (body.length > PLATFORM_EVENT_MAX_BODY) return Response.json({ error: "too_large" }, { status: 413 });
  const id = req.headers.get("nxeon-webhook-id"), ts = req.headers.get("nxeon-webhook-timestamp"), sig = req.headers.get("nxeon-signature");
  if (!id || !ts || !sig || !/^\d{9,11}$/.test(ts) || !/^[A-Za-z0-9_:.-]{4,200}$/.test(id)) return Response.json({ error: "unsigned" }, { status: 401 });
  if (Math.abs(Math.floor(now / 1000) - Number(ts)) > PLATFORM_EVENT_TOLERANCE_S) return Response.json({ error: "stale" }, { status: 401 });
  const want = `v1=${createHmac("sha256", o.secret).update(`${id}.${ts}.${body}`).digest("hex")}`;
  if (!sig.split(/[ ,]+/).some((s) => safeEqual(s, want))) return Response.json({ error: "bad_signature" }, { status: 401 });
  if (o.done.has(id, now)) return Response.json({ ok: true, duplicate: true });
  let e: PlatformEventIn;
  try { e = JSON.parse(body); if (!e || e.id !== id || typeof e.type !== "string" || typeof e.data !== "object" || e.data === null) throw new Error(); }
  catch { return Response.json({ error: "invalid_event" }, { status: 400 }); }
  const h = o.handlers[e.type];
  if (!h) { o.done.add(id, now); return Response.json({ ok: true, ignored: e.type }); }
  try {
    const r = await h(e);
    o.done.add(id, now);
    return Response.json({ ok: true, result: r ?? null });
  } catch (err) {
    console.error("[cyrus-platform-events]", e.type, id, (err as Error).message);
    return Response.json({ error: "retry" }, { status: 500 });
  }
}
