const stripe = (): Stripe => { const h = hostStripe(); if (!h) throw new Error("Stripe is not configured"); return h.client(); };
const stripeConfigured = () => !!hostStripe()?.configured();
const stripePublishableKey = () => hostStripe()?.publishableKey() ?? "";
const createCheckoutSessionLogged = (params: Stripe.Checkout.SessionCreateParams, options?: Stripe.RequestOptions) => {
  const h = hostStripe();
