/** Tests inject a fake client (no network). */
export function setCyrusStripeForTests(s: StripeLike | null) { override = s; priceCache = null; }
const sc = (): StripeLike => override ?? stripe();
const configured = () => !!override || stripeConfigured();
const appBase = () => process.env.APP_URL ?? "http://localhost:3000";
const ts = (n: number | null | undefined) => (n ? new Date(n * 1000) : null);
const idOf = (x: string | { id: string } | null | undefined) => (typeof x === "string" ? x : x?.id ?? null);

// ---------------------------------------------------------------------------
// Prices
// ---------------------------------------------------------------------------

export type PlanPrice = { tier: PlanTier; id: string; unitAmount: number | null; currency: string; livemode: boolean };
let priceCache: { at: number; key: string; prices: Record<PlanTier, PlanPrice | null> } | null = null;

/** The three plan prices: Setting override ids, else the price with lookup_key cyrus_plan_<tier>_v1. */
export async function planPrices(cfg?: TokenConfig): Promise<Record<PlanTier, PlanPrice | null>> {
  const c = cfg ?? (await loadTokenConfig());
  const empty = { katara: null, saka: null, all: null } as Record<PlanTier, PlanPrice | null>;
  if (!configured()) return empty;
  const key = JSON.stringify(c.plan.priceIds);
  if (priceCache && priceCache.key === key && Date.now() - priceCache.at < 10 * 60_000) return priceCache.prices;
  const out = { ...empty };
  const toPlan = (tier: PlanTier, p: Stripe.Price): PlanPrice => ({ tier, id: p.id, unitAmount: p.unit_amount, currency: p.currency, livemode: p.livemode });
  try {
    const listed = await sc().prices.list({ lookup_keys: PLAN_TIERS.map(PLAN_LOOKUP_KEY), active: true, limit: 10 });
    for (const p of listed.data) { const t = tierFromLookupKey(p.lookup_key); if (t && !out[t]) out[t] = toPlan(t, p); }
    for (const t of PLAN_TIERS) {
      const id = c.plan.priceIds[t];
      if (id) out[t] = toPlan(t, await sc().prices.retrieve(id));
    }
  } catch (e) {
    console.error("[cyrus-tokens] price lookup failed", (e as Error).message);
    return empty;
  }
  priceCache = { at: Date.now(), key, prices: out };
  return out;
}

export async function tierOfPrice(price: string | Stripe.Price | null | undefined, cfg?: TokenConfig): Promise<PlanTier | null> {
  if (!price) return null;
  if (typeof price !== "string") {
    const t = tierFromLookupKey(price.lookup_key) ?? (price.metadata?.cyrus_tier as PlanTier | undefined);
    if (t && (PLAN_TIERS as readonly string[]).includes(t)) return t as PlanTier;
  }
  const id = idOf(price);
  const prices = await planPrices(cfg);
  return PLAN_TIERS.find((t) => prices[t]?.id === id) ?? null;
}

