/** A paid top-up session -> tokens (idempotent per session). Returns tokens granted (0 if replay/unpaid). */
export async function fulfilTopup(session: Stripe.Checkout.Session): Promise<number> {
  const md = session.metadata ?? {};
  if (md.cyrusKind !== "topup" || !md.cyrusUserId || session.payment_status !== "paid" || session.mode !== "payment") return 0;
  const cfg = await loadTokenConfig();
  const paidCents = session.amount_total ?? 0;
  // The amount actually paid decides the tokens; the metadata figure is only a cap.
  const tokens = Math.min(Number(md.cyrusTokens) || 0, topupTokens(paidCents, cfg));
  // r44: through the purchase path (direct credit, or the signed webhook/outbox when CYRUS_PURCHASE_EVENTS=1), same
  // idemKey as before, so a return-leg + webhook race or a redelivery still credits exactly once
  const r = await deliverPurchase(topupSessionEnvelope(session, md.cyrusUserId, tokens, paidCents, cfg));
  return r.tokens;
}

/** The purchase envelope of a paid top-up session (also used by the reconcile sweep). */
export function topupSessionEnvelope(session: Stripe.Checkout.Session, userId: string, tokens: number, paidCents: number, cfg: { topup: { expiryDays: number } }) {
  const at = session.created ? new Date(session.created * 1000) : new Date();
  return cardTopupEnvelope({
    userId, sessionId: session.id, tokens, paidCents, expiresAt: new Date(Date.now() + cfg.topup.expiryDays * DAY),
    paymentIntent: idOf(session.payment_intent as string | { id: string } | null), livemode: session.livemode,
  }, at);
}

/** r44: recent paid Cyrus top-up sessions whose event never landed get credited directly (CYRUS_PURCHASE_EVENTS only). */
export async function reconcileCardTopupSessions(sinceMs = Date.now() - 3 * DAY): Promise<{ checked: number; credited: number }> {
  if (process.env.CYRUS_PURCHASE_EVENTS !== "1" || !configured()) return { checked: 0, credited: 0 };
  const cfg = await loadTokenConfig();
  const list = await sc().checkout.sessions.list({ created: { gte: Math.floor(sinceMs / 1000) }, limit: 100 });
  const envs = list.data.filter((x) => x.metadata?.cyrusKind === "topup" && x.metadata?.cyrusUserId && x.payment_status === "paid" && x.mode === "payment")
    .map((x) => topupSessionEnvelope(x, x.metadata!.cyrusUserId!, Math.min(Number(x.metadata!.cyrusTokens) || 0, topupTokens(x.amount_total ?? 0, cfg)), x.amount_total ?? 0, cfg));
  return reconcileCardTopups(envs);
}

/** The Checkout return leg (and the webhook's checkout events). */
export async function fulfilCyrusSession(sessionOrId: string | Stripe.Checkout.Session): Promise<{ kind: "plan" | "topup" | "none"; userId: string | null; tokens: number }> {
  const session = typeof sessionOrId === "string" ? await sc().checkout.sessions.retrieve(sessionOrId) : sessionOrId;
  const md = session.metadata ?? {};
  if (!md.cyrusUserId) return { kind: "none", userId: null, tokens: 0 };
  if (md.cyrusKind === "topup") return { kind: "topup", userId: md.cyrusUserId, tokens: await fulfilTopup(session) };
  if (md.cyrusKind === "plan" && session.subscription) {
    const before = await db.cyrusTokenLedger.aggregate({ where: { userId: md.cyrusUserId, source: "plan", kind: "purchase" }, _sum: { delta: true } });
