import { NextResponse } from "next/server";
import { fulfilCyrusSession } from "@/lib/cyrus/tokens/billing";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { bridgeConfig, CYRUS_HOST_HEADER } from "@/lib/cyrus/bridge/config";

export const dynamic = "force-dynamic";

/**
 * Stripe Checkout return leg for Cyrus purchases. Runs the SAME idempotent fulfilment as
 * the webhook (tokens are keyed by session / invoice id), then sends the customer back
 * to Cyrus. Safe to hit twice; grants only to the session's own metadata account and
 * only for a paid session.
 */
export async function GET(req: Request) {
  const url = new URL(req.url);
  const id = url.searchParams.get("session_id") || "";
  // On cyrus.my (CYRUS_DOMAIN_MODE) the studio is /studio on the Cyrus origin; on Nxeon it is /dashboard/cyrus.
  const onCyrus = req.headers.get(CYRUS_HOST_HEADER) === "1";
  const base = onCyrus ? bridgeConfig().cyrusOrigin : (process.env.APP_URL ?? url.origin);
  const studio = onCyrus ? "/studio" : "/dashboard/cyrus";
  const ip = trustedClientIp(req); // nginx's hop (the first XFF entry is client-written: a free bucket per request)
  if (!/^cs_(test|live)_[A-Za-z0-9]+$/.test(id) || !checkRateLimit(`cyrus:return:${ip}`, { max: 20, windowMs: 60_000 }).ok) {
    return NextResponse.redirect(`${base}${studio}`);
  }
  let state = "pending";
  try {
    const r = await fulfilCyrusSession(id);
    if (r.kind !== "none") state = "ok";
  } catch (e) {
    console.error("[cyrus-tokens] return", id, (e as Error).message);
  }
  return NextResponse.redirect(`${base}${studio}?tokens=${state}`);
}
