  const q = new URL(req.url).searchParams;
  const build = q.get("build");
  const mod = q.get("mod");
  const id = build ?? mod;
  if (!id || !ID.test(id)) return NOT_FOUND();
  const out = build ? await liveBuildSpend(user.id, id) : await modSpend(user.id, id);
  if (!out) return NOT_FOUND();
  return NextResponse.json(out, { headers: { "Cache-Control": "no-store" } });
