  const gone = new Set<string>();
  let after: string | null = null;
  for (let page = 0; page < 200; page++) {
    const grants = await d.store.activePage(after, d.pageSize ?? 200);
    if (!grants.length) break;
    after = grants[grants.length - 1].id;
    const servers = new Map((await d.load([...new Set(grants.map((g) => g.serverId))])).map((s) => [s.id, s]));
    for (const g of grants) {
      out.checked++;
      const s = servers.get(g.serverId);
      if (!s || s.status === "DELETING" || s.userId !== g.userId) {
        if (gone.has(`${g.serverId}:${g.userId}`)) continue;
        gone.add(`${g.serverId}:${g.userId}`);
        await emit(serverDeleted({ userId: g.userId, serverId: g.serverId, at: now() }));
        // a transfer to another account ends the grant too (it was the old owner's consent)
        out.deleted += await revokeServerGrants(d.store, g.serverId, s && s.userId !== g.userId ? "server_transferred" : "server_deleted", async (e) => { await emit(grantChanged(e.type, e.grant, e.at)); }, now());
        continue;
      }
      if (!g.seenAt) { await d.store.markSeen(g.id, { version: s.version, loader: s.loader, at: now() }); continue; }
      if (g.seenVersion !== s.version || g.seenLoader !== s.loader) {
        await emit(serverVersionChanged({ userId: g.userId, serverId: s.id, from: g.seenVersion, to: s.version, loader: s.loader, at: now() }));
        await d.store.markSeen(g.id, { version: s.version, loader: s.loader, at: now() });
        out.changed++;
      }
    }
  }
  return out;
}

