}
// Cyrus AI spend caps (r40, cost governance). Read on the build path before any token hold or AI call.
// All caps default to 0 = off: with no cap set this does no database read and changes nothing. With a cap set, a read
// error refuses the build (fail closed: an unreadable spend must not mean unlimited spend). Running builds are never
// stopped; caps only gate NEW builds. Pure decision: lib/cyrus/admin/cost.ts spendCapDecision.
import { cyrusDb as db } from "./db";
import { getHost } from "./host";
import { anyCap, COST_SETTINGS, parseCostCaps, spendCapDecision, utcDayStart, utcMonthStart, type CapDecision, type CostCaps } from "./admin/cost";

export async function loadCostCaps(): Promise<CostCaps> {
  return parseCostCaps(await getHost().settings.readStored(Object.values(COST_SETTINGS)));
}

const sum = async (where: Record<string, unknown>) => (await db.modBuild.aggregate({ where, _sum: { costUsd: true } }))._sum.costUsd ?? 0;

export async function checkSpendCaps(userId: string, now = new Date()): Promise<CapDecision> {
  let caps: CostCaps;
  try { caps = await loadCostCaps(); } catch { return { ok: false, status: 503, code: "platform_spend_cap", error: "Cyrus building is not available right now. Please try again shortly." }; }
  if (!anyCap(caps)) return { ok: true };
  try {
    const day = utcDayStart(now), month = utcMonthStart(now);
    const [userTodayUsd, userMonthUsd, platformTodayUsd] = await Promise.all([
      caps.userDailyCapUsd > 0 ? sum({ userId, createdAt: { gte: day } }) : 0,
      caps.userMonthlyCapUsd > 0 ? sum({ userId, createdAt: { gte: month } }) : 0,
      caps.platformDailyCapUsd > 0 ? sum({ createdAt: { gte: day } }) : 0,
    ]);
    return spendCapDecision({ caps, userTodayUsd, userMonthUsd, platformTodayUsd });
  } catch {
    return { ok: false, status: 503, code: "platform_spend_cap", error: "Cyrus building is not available right now. Please try again shortly." };
  }
}
