// r44: download a finished Cyrus data export (lib/cyrus/app/data-jobs.ts). Owner only, while `ready` and unexpired;
// anything else (other user's id, expired, flag off, gate closed) is a plain 404. Every download is audited.
import { readFile } from "node:fs/promises";
import { cyrusDb } from "@/lib/cyrus/db";
import { getHost } from "@/lib/cyrus/host";
import { downloadable } from "@/lib/cyrus/app/data-jobs";
import { insideExportDir } from "@/lib/cyrus/app/data-jobs.server";
import { appViewerOrNull } from "@/app/dashboard/cyrus/app/_gate";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
const nf = () => new Response("Not found", { status: 404, headers: { "cache-control": "no-store" } });

export async function GET(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  if (process.env.CYRUS_DATA_JOBS !== "1") return nf();
  const v = await appViewerOrNull();
  if (!v) return nf();
  const id = (await ctx.params).id;
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) return nf();
  const row = await cyrusDb.cyrusDataRequest.findUnique({ where: { id } }).catch(() => null);
  if (!downloadable(row, v.user.id, new Date()) || !insideExportDir(row.archivePath)) return nf();
  const buf = await readFile(row.archivePath).catch(() => null);
  if (!buf) return nf();
  await getHost().audit.append({ userId: v.user.id, action: "cyrus.data.export.download", category: "cyrus", target: id, detail: JSON.stringify({ bytes: buf.length }) }).catch(() => {});
  return new Response(new Uint8Array(buf), {
    headers: { "content-type": "application/zip", "content-disposition": `attachment; filename="cyrus-data-${row.createdAt.toISOString().slice(0, 10)}.zip"`, "cache-control": "no-store", "x-content-type-options": "nosniff" },
  });
}

